from pathlib import Pathimport numpy as npimport pandas as pdROOT = Path(__file__).resolve().parent.parentRESULTS = ROOT / 'results'INPUT = RESULTS / 'satellite_case_studies.csv'if not INPUT.exists():    raise FileNotFoundError(f'Missing {INPUT}. Run prepare_satellite_case_studies.py first.')cases = pd.read_csv(INPUT)cases['norad_id'] = pd.to_numeric(cases['norad_id'], errors='raise').astype(int)# Explicitly sourced spacecraft information. Mass is mass AT LAUNCH,# not mass in May 2024. No projected drag area or actual maneuver records# are inferred from body dimensions or launch mass.verified = {    43477: dict(mission_class_researched='Earth science / gravimetry',                launch_mass_kg=600.2,                propulsion_family_researched='Cold-gas propulsion (formation/orbit control)',                mass_source='https://www.jpl.nasa.gov/news/press_kits/grace-fo/facts/',                propulsion_source='https://www.jpl.nasa.gov/news/press_kits/grace-fo/mission/spacecraft/',                note='NASA quotes 600.2 kg per GRACE-FO spacecraft including propellant at launch; not current mass.'),    42063: dict(mission_class_researched='Earth observation / multispectral imaging',                launch_mass_kg=1140.0,                propulsion_family_researched='Hydrazine propulsion',                mass_source='https://www.esa.int/Applications/Observing_the_Earth/Copernicus/Sentinel-2/Facts_and_figures',                propulsion_source='https://www.esa.int/articles/about-us/directorates/operations/sentinel-2-operations',                note='ESA quotes about 1140 kg at launch. Dimensions are NOT projected drag area.'),    54361: dict(mission_class_researched='Earth observation / ocean monitoring',                launch_mass_kg=np.nan,                propulsion_family_researched='Not verified',                mass_source='',                propulsion_source='',                note='Mass sources differ; not populated until reconciled. Vehicle thrusters are not necessarily satellite thrusters.'),    58316: dict(mission_class_researched='Earth observation / imaging',                launch_mass_kg=np.nan,                propulsion_family_researched='Not verified for this specific spacecraft',                mass_source='',                propulsion_source='',                note='Planet Dove-family characteristics are not automatically exact for this spacecraft.'),}for col in ['mission_class_researched','launch_mass_kg','propulsion_family_researched',            'mass_source','propulsion_source','note']:    cases[col] = [verified.get(int(i),{}).get(col,np.nan if col=='launch_mass_kg' else '')                  for i in cases['norad_id']]# Idealized two-impulse, coplanar circular-to-circular Hohmann orbit raise.# These are illustrative altitude restoration SCENARIOS, not a measure# of storm-caused decay or observed satellite maneuvering.MU = 398600.4418  # km^3 / s^2R_E = 6371.0  # km, consistent with earlier altitude conventiondef hohmann_total_dv_ms(alt_km, raise_km):    r1 = R_E + alt_km    r2 = r1 + raise_km    transfer_a = (r1+r2)/2    v1 = np.sqrt(MU/r1)    v2 = np.sqrt(MU/r2)    vt1 = np.sqrt(MU*(2/r1 - 1/transfer_a))    vt2 = np.sqrt(MU*(2/r2 - 1/transfer_a))    return 1000 * ((vt1-v1) + (v2-vt2))if 'altitude_km' not in cases.columns:    raise KeyError('Expected altitude_km in case-study CSV')scenarios=[]for _, row in cases.iterrows():    for rise in [1.0, 10.0]:        scenarios.append(dict(            norad_id=int(row['norad_id']),            satellite_name=row['satellite_name'],            altitude_km=float(row['altitude_km']),            altitude_restored_km=rise,            ideal_two_impulse_dv_ms=hohmann_total_dv_ms(float(row['altitude_km']),rise),            interpretation='Hypothetical circular-orbit correction; NOT actual storm-induced delta-v',        ))p1=RESULTS / 'satellite_case_studies_sourced.csv'p2=RESULTS / 'satellite_orbit_raise_scenarios.csv'cases.to_csv(p1,index=False)pd.DataFrame(scenarios).to_csv(p2,index=False)print('\nCASE STUDIES WITH INITIAL VERIFIED SOURCES:')print(cases[['norad_id','satellite_name','mission_class_researched','launch_mass_kg','propulsion_family_researched']].to_string(index=False))print('\nIDEALIZED 10 km ORBIT RESTORATION (NOT STORM ATTRIBUTION):')s = pd.DataFrame(scenarios)print(s[s['altitude_restored_km']==10][['satellite_name','altitude_km','ideal_two_impulse_dv_ms']].to_string(index=False, float_format=lambda x:f'{x:.4f}'))print(f'\nSaved: {p1}\nSaved: {p2}')